import{_ as r}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as e,o as a,af as o}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const w=JSON.parse('{"title":"千问教程","description":"写给谁：第一次打开 qianwen.com 的前端工程师。你会完成第一句对话，并知道电脑端和 App 的官方入口。","frontmatter":{"title":"千问教程","description":"写给谁：第一次打开 qianwen.com 的前端工程师。你会完成第一句对话，并知道电脑端和 App 的官方入口。","domain":"product","tags":["chat"],"role":"tutorial"},"headers":[],"relativePath":"zh/products/qwen/qwen.md","filePath":"zh/products/qwen/qwen.md","lastUpdated":1787107158000}'),n={name:"zh/products/qwen/qwen.md"};function l(i,t,d,s,h,p){return a(),e("div",null,[...t[0]||(t[0]=[o('<h1 id="千问教程" tabindex="-1">千问教程 <a class="header-anchor" href="#千问教程" aria-label="Permalink to &quot;千问教程&quot;">​</a></h1><blockquote><p>先打开 <a href="https://www.qianwen.com/" target="_blank" rel="noreferrer">qianwen.com</a> 或 <a href="https://www.qianwen.com/download" target="_blank" rel="noreferrer">PC 客户端页</a>。本页只复述能在官方页核对的入口和能力。</p></blockquote><h2 id="目标与非目标" tabindex="-1">目标与非目标 <a class="header-anchor" href="#目标与非目标" aria-label="Permalink to &quot;目标与非目标&quot;">​</a></h2><p><strong>写给谁：</strong> 第一次用千问的前端工程师。首页按钮文案是 <strong>登录</strong>；具体登录方式以页面为准。</p><p><strong>你会完成：</strong> 在网页或客户端里发出第一句；知道电脑端和官方 App 怎么下。</p><p><strong>不会做：</strong> 淘宝 / 支付宝注册教程、通义灵码 / Qoder 安装、百炼 API、编造会员价。</p><h2 id="先决条件" tabindex="-1">先决条件 <a class="header-anchor" href="#先决条件" aria-label="Permalink to &quot;先决条件&quot;">​</a></h2><ul><li>能打开 <code>www.qianwen.com</code>（部分网络会把该域名解析到 <code>198.18.0.0/15</code>，先换 DNS / 关 Fake-IP 再判断「打不开」）。</li><li>客户端系统要求以官方页为准，两处不要混成一个数： <ul><li>App Store：设备需装有 <strong>iOS 14.0</strong> 或更高版本；iPad 为 <strong>iPadOS 14.0</strong> 或更高。</li><li>Windows / Mac / Android / HarmonyOS 的数字门槛：2026-08-19 在下载页和协议里<strong>没有</strong>读到可引用的最低版本。</li></ul></li></ul><h2 id="_15-分钟内打开" tabindex="-1">15 分钟内打开 <a class="header-anchor" href="#_15-分钟内打开" aria-label="Permalink to &quot;15 分钟内打开&quot;">​</a></h2><h3 id="_1-选一个官方入口" tabindex="-1">1. 选一个官方入口 <a class="header-anchor" href="#_1-选一个官方入口" aria-label="Permalink to &quot;1. 选一个官方入口&quot;">​</a></h3><table tabindex="0"><thead><tr><th>端</th><th>怎么走</th><th>来源</th></tr></thead><tbody><tr><td>网页</td><td>打开 <a href="https://www.qianwen.com/" target="_blank" rel="noreferrer">qianwen.com</a>，点 <strong>登录</strong></td><td>首页</td></tr><tr><td>Windows / macOS</td><td>首页 <strong>下载电脑端</strong>，或打开 <a href="https://www.qianwen.com/download" target="_blank" rel="noreferrer">qianwen.com/download</a>；Windows 也可走 <a href="https://apps.microsoft.com/detail/xp8m1sgl1lzr2f" target="_blank" rel="noreferrer">Microsoft Store · 千问</a>（id <code>XP8M1SGL1LZR2F</code>）</td><td>首页、下载页、Microsoft Store</td></tr><tr><td>iOS / iPad</td><td>App Store「千问 - 阿里AI助手」（id <code>6466733523</code>）</td><td><a href="https://apps.apple.com/cn/app/%E5%8D%83%E9%97%AE-%E9%98%BF%E9%87%8Cai%E5%8A%A9%E6%89%8B/id6466733523" target="_blank" rel="noreferrer">App Store</a></td></tr><tr><td>Android</td><td>应用宝「千问」，包名 <code>com.aliyun.tongyi</code></td><td><a href="https://sj.qq.com/appdetail/com.aliyun.tongyi" target="_blank" rel="noreferrer">应用宝</a></td></tr></tbody></table><p>协议还写了 <strong>HarmonyOS</strong>、<strong>浏览器插件</strong>、<strong>小程序</strong>、<strong>H5</strong>（<a href="https://terms.alicdn.com/legal-agreement/terms/c_end_product_protocol/20231011201348415/20231011201348415.html" target="_blank" rel="noreferrer">用户服务协议</a> 1.1）。2026-08-19 没有找到这几个形态的千问助手独立安装页，本教程不写步骤。阿里云帮助中心的 <a href="https://help.aliyun.com/zh/qwenwork/harmonyos-installation-guide" target="_blank" rel="noreferrer">千问办公 HarmonyOS 指南</a> 是另一条产品线，不要当成 qianwen.com 助手安装。</p><p>登录：协议 5.1 写「通过手机号进行账号注册并登录，或者选择……第三方账号（淘宝、支付宝、Apple）」。那是登录手段，不是淘宝教程。</p><p>国际站 <a href="https://chat.qwen.ai/" target="_blank" rel="noreferrer">chat.qwen.ai</a> 页名是 <strong>Qwen Studio</strong>，按钮是 <strong>Log in / Sign up</strong>。它不是本页的安装路径。</p><h3 id="_2-发出第一句" tabindex="-1">2. 发出第一句 <a class="header-anchor" href="#_2-发出第一句" aria-label="Permalink to &quot;2. 发出第一句&quot;">​</a></h3><p>未登录首页可见：「你好，我是千问」。顶栏有 <strong>API 服务</strong>、<strong>下载电脑端</strong>、<strong>登录</strong>。当前模型标签是 <strong>Qwen3.7-千问</strong>。</p><p>登录后点 <strong>新建对话</strong>，在输入框提问。底部写「继续使用即表示您同意用户协议和隐私政策」——先打开协议再当免责套话忽略。</p><p>不要点顶栏 <strong>API 服务</strong> 当「开始聊天」。那是同厂 API 入口，教程在 #85，这里不写。</p><h3 id="_3-电脑端-划词和侧边栏" tabindex="-1">3. 电脑端：划词和侧边栏 <a class="header-anchor" href="#_3-电脑端-划词和侧边栏" aria-label="Permalink to &quot;3. 电脑端：划词和侧边栏&quot;">​</a></h3><p>只在需要桌面唤起时装客户端。官方下载页 title：<code>千问PC客户端 - 阿里AI助手</code>。搜索引擎收录的下载页原文包括：支持 AI 搜索、网页总结、AI PPT、AI 生图、PPT 创作和录音纪要；划词解读翻译。</p><p>用户协议 1.2 原文：Windows 及 Mac 客户端支持网页搜索与浏览，可借助<strong>千问侧边栏</strong>实现「边浏览边对话、边看边总结、即问即答」。</p><p>首页横幅另写：</p><table tabindex="0"><thead><tr><th>动作</th><th>官方原文</th></tr></thead><tbody><tr><td>办公助理</td><td>「千问办公助理上线 解锁本地任务能力」；「支持手机远程操控，丰富技能与连接器，多格式交付」</td></tr><tr><td>划词</td><td>「千问快捷划词，全局使用的效率工具」；「随心划选浏览内容，即可唤醒千问总结、翻译和创作」</td></tr><tr><td>录音纪要</td><td>「断网也能稳定录，纪要自动整理，重要内容一句不漏」</td></tr></tbody></table><p>电脑端快捷键：2026-08-19 <strong>没有</strong>在公开页读到可引用的组合键。 以客户端设置为准，不要抄第三方博客。</p><h2 id="官方能力-按出处分组" tabindex="-1">官方能力（按出处分组） <a class="header-anchor" href="#官方能力-按出处分组" aria-label="Permalink to &quot;官方能力（按出处分组）&quot;">​</a></h2><h3 id="首页在说什么" tabindex="-1">首页在说什么 <a class="header-anchor" href="#首页在说什么" aria-label="Permalink to &quot;首页在说什么&quot;">​</a></h3><p><a href="https://www.qianwen.com/" target="_blank" rel="noreferrer">qianwen.com</a> 可见：</p><ul><li>侧栏：<strong>新建对话</strong>、<strong>云空间</strong>、<strong>AI创作</strong>、<strong>定时任务</strong></li><li>模式：<strong>快速</strong>、<strong>办公助理</strong>、<strong>本地电脑</strong></li><li>能力入口：PPT创作、AI生视频、AI生图、代码、翻译、AI写作、研究、录音纪要、千问高考、音视频速读</li><li>横幅：办公助理、千问输入法、录音纪要、快捷划词</li></ul><p>「本地电脑」是产品里的一个模式，不是让你去装通义灵码。</p><h3 id="商店长描述还列了什么" tabindex="-1">商店长描述还列了什么 <a class="header-anchor" href="#商店长描述还列了什么" aria-label="Permalink to &quot;商店长描述还列了什么&quot;">​</a></h3><p>App Store 与应用宝「简介」在 2026-08-19 一致，包括：</p><ul><li>对话问答：优质知识源、结构化答案、思考研究</li><li>办公助理：交付网页 / 应用 / PPT / Word / Excel / 图片；skills 技能</li><li>定时任务：周期性和一次性</li><li>语音通话：7×24；陪玩、睡前故事、带娃讲题、语音打车</li><li>AI 智能体：智能体广场；对话里 <code>@</code> 唤起</li><li>AI 生活帮手：外卖 / 酒店 / 餐厅 / 政务 / 购物建议</li><li>AI 写作、AI PPT、智能编辑器（PDF / WORD / PPT / EXCEL 互转）</li><li>文档阅读：一次上传 10 个文档 / 图片，500 页超长文</li><li>代码处理：一句话生成小程序 / 网页 / 小游戏 / SQL；上传代码或截图检查与改写</li><li>实时记录：离线或实时语音转文字，会议纪要</li><li>AI 创作：Wan 2.7 视频；Qwen-Image 2.0 生图 / P 图 / 修图</li><li>学习辅导：小讲堂、拍题、作业批改、5 亿资料库</li></ul><p>这是<strong>对话与交付</strong>，不是克隆仓库、开 PR、接 MCP。仓库级编码去 <a href="https://qoder.com.cn/" target="_blank" rel="noreferrer">通义灵码 / Qoder CN</a>（本站 #84，这里不写教程）。</p><p>应用宝另有一段「通义介绍」仍写通义 APP、全民舞王、通义听悟、集成通义灵码。那是旧简介，<strong>不要</strong>当现行功能清单。</p><h3 id="千问输入法" tabindex="-1">千问输入法 <a class="header-anchor" href="#千问输入法" aria-label="Permalink to &quot;千问输入法&quot;">​</a></h3><p>首页横幅：「千问输入法 App 全新上线」；「最快 300 字/分，说话即成稿，支持 9 种方言，无广告」。应用宝「厂商其它应用」列出 <code>com.qianwen.ime</code>。本教程不写输入法安装步骤。</p><h2 id="模型文案不要选边" tabindex="-1">模型文案不要选边 <a class="header-anchor" href="#模型文案不要选边" aria-label="Permalink to &quot;模型文案不要选边&quot;">​</a></h2><p>几处官方说法同时存在（2026-08-19）：</p><table tabindex="0"><thead><tr><th>出处</th><th>原文</th></tr></thead><tbody><tr><td>首页</td><td>模型标签 <strong>Qwen3.7-千问</strong>；description 写「最强Qwen大模型」</td></tr><tr><td>App Store</td><td>「最新、最强千问大模型」；创作侧写 <strong>Wan 2.7</strong>、<strong>Qwen-Image 2.0</strong></td></tr><tr><td>Qwen Studio（国际站，非本教程）</td><td>页上可见 <strong>Qwen3.7-Plus</strong></td></tr><tr><td>通义实验室</td><td>模型卡：Qwen3-Max / Qwen-Plus / Qwen-Flash 等</td></tr></tbody></table><p>以你客户端里实际可选的名称为准。不要写「现在默认 Qwen3.7」。模型原理见 <a href="/zh/tech/fundamentals/LLM.html">Learn LLM</a>。</p><h2 id="协议与数据" tabindex="-1">协议与数据 <a class="header-anchor" href="#协议与数据" aria-label="Permalink to &quot;协议与数据&quot;">​</a></h2><p>使用前打开：</p><ul><li><a href="https://terms.alicdn.com/legal-agreement/terms/c_end_product_protocol/20231011201348415/20231011201348415.html" target="_blank" rel="noreferrer">千问用户服务协议</a>（更新 2026-03-20，生效 2026-03-27）</li><li><a href="https://terms.alicdn.com/legal-agreement/terms/privacy_policy_full/20231011201849846/20231011201849846.html" target="_blank" rel="noreferrer">千问产品隐私政策</a></li><li>App 内购买另见 <a href="https://terms.alicdn.com/legal-agreement/terms/c_end_product_protocol/20260728154300619/20260728154300619.html" target="_blank" rel="noreferrer">会员协议</a></li></ul><p>协议服务范围原文包括网站、网页、客户端（iOS、Android、Windows、Mac、HarmonyOS）、浏览器插件、小程序、H5。条款正文以协议当前文本为准，本页不转述授权范围。</p><p>经营者原文：上海智信普惠科技有限公司。适用场合原文：「个人学习、研究、欣赏、日常生活、娱乐使用」。</p><p>套餐：App Store 标「免费 · App 内购买」。<strong>没有</strong>在 qianwen.com 找到价目表，不要编数字。</p><h2 id="常见陷阱" tabindex="-1">常见陷阱 <a class="header-anchor" href="#常见陷阱" aria-label="Permalink to &quot;常见陷阱&quot;">​</a></h2><ul><li><strong>把千问当成 Claude Code / Cursor。</strong> 官方没有千问 CLI，也没有官方 IDE 插件页。编码工具是通义灵码 / Qoder CN（#84）。</li><li><strong>把 <code>chat.qwen.ai</code> 收藏成「千问英文版」。</strong> 那一页的产品名是 <strong>Qwen Studio</strong>。</li><li><strong>跟着应用宝「通义介绍」写全民舞王 / 通义听悟。</strong> 现行首页和 App Store 简介没有复现这些栏目。</li><li><strong>为插件 / 小程序 / HarmonyOS 写安装步骤。</strong> 协议有名字，没有找到千问助手独立安装页。</li><li><strong>把百炼 Token Plan 的价格抄进笔记。</strong> 那是 #85。</li><li><strong>用淘宝账号登录之后开始写淘宝教程。</strong> 登录手段 ≠ 产品范围。</li></ul><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ul><li>回查入口和链接：<a href="./qwen-cheatsheet.html">速查表</a></li><li>分清名字：<a href="./qwen-glossary.html">术语表</a></li><li>回家族图：<a href="./">学习地图</a></li></ul>',50)])])}const f=r(n,[["render",l]]);export{w as __pageData,f as default};
